import{_ as t,o as a,c as l,a3 as i}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"Bildmodelle lokal","description":"A1111 oder ComfyUI lokal; MiniTavern LAN-Bildgenerierung ohne Cloud-Image-API.","frontmatter":{"title":"Bildmodelle lokal","description":"A1111 oder ComfyUI lokal; MiniTavern LAN-Bildgenerierung ohne Cloud-Image-API.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"Bildmodelle lokal · MiniTavern Docs"}],["meta",{"property":"og:description","content":"A1111 oder ComfyUI lokal; MiniTavern LAN-Bildgenerierung ohne Cloud-Image-API."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/local/image-gen"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/local/image-gen"}]]},"headers":[],"relativePath":"de/local/image-gen/index.md","filePath":"de/local/image-gen/index.md","lastUpdated":1787224147000}'),n={name:"de/local/image-gen/index.md"};function o(r,e,d,s,h,c){return a(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="bildmodelle-lokal" tabindex="-1">Bildmodelle lokal <a class="header-anchor" href="#bildmodelle-lokal" aria-label="Permalink to &quot;Bildmodelle lokal&quot;">​</a></h1><p>MiniTavern unterstützt Cloud-Bild (OpenAI / Gemini / OpenRouter / Qwen) und <strong>lokale</strong> Stable-Diffusion-Dienste:</p><table tabindex="0"><thead><tr><th>Lokales Backend</th><th>App-Plattform</th><th>Standardport</th></tr></thead><tbody><tr><td><a href="/ultra_guides/de/local/image-gen/a1111">AUTOMATIC1111 / SD WebUI</a></td><td>A1111(SD WebUI)</td><td><code>7860</code></td></tr><tr><td><a href="/ultra_guides/de/local/image-gen/comfyui">ComfyUI</a></td><td>ComfyUI</td><td><code>8188</code> (Desktop oft <code>8000</code>)</td></tr></tbody></table><p>MiniTavern auf dem Handy <strong>führt keine</strong> Diffusionsmodelle aus; Bilder entstehen am PC (oder Cloud-GPU), die App sendet Requests und zeigt Ergebnisse.</p><h2 id="was-sie-brauchen" tabindex="-1">Was Sie brauchen <a class="header-anchor" href="#was-sie-brauchen" aria-label="Permalink to &quot;Was Sie brauchen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Punkt</th><th>Empfehlung</th></tr></thead><tbody><tr><td>PC</td><td>Windows am einfachsten; macOS / Linux möglich</td></tr><tr><td>GPU</td><td><strong>NVIDIA 6GB+</strong> angenehm (SD 1.5); SDXL / größere Modelle <strong>8–12GB+</strong></td></tr><tr><td>ohne dGPU</td><td>CPU (sehr langsam) oder Cloud-GPU stundenweise (nicht free)</td></tr><tr><td>Netz</td><td>Handy und PC gleiches Wi‑Fi (kein Gastnetz mit Isolation)</td></tr><tr><td>Disk</td><td>Modelle oft <strong>2–10GB+</strong> / Stück, Platz vorhalten</td></tr></tbody></table><p>Ohne GPU und ohne Deployment: <a href="/ultra_guides/de/free-cloud/#kostenlose-bildgenerierung">Kostenlose Cloud · Bild</a> oder vorerst nur chatten.</p><h2 id="welcher-weg" tabindex="-1">Welcher Weg <a class="header-anchor" href="#welcher-weg" aria-label="Permalink to &quot;Welcher Weg&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Für wen</th><th>Schwierigkeit</th></tr></thead><tbody><tr><td><a href="/ultra_guides/de/local/image-gen/a1111">A1111</a></td><td>klassisches WebUI, klare Parameter, üblich mit Tavern</td><td>mittel</td></tr><tr><td><a href="/ultra_guides/de/local/image-gen/comfyui">ComfyUI</a></td><td>Workflows / neue Modelle schnell; App nutzt eingebauten Default-Workflow</td><td>mittel</td></tr></tbody></table><p>Beide enden bei: <a href="/ultra_guides/de/local/image-gen/connect-app">Bildverbindung in MiniTavern</a>.</p><h2 id="empfohlene-reihenfolge" tabindex="-1">Empfohlene Reihenfolge <a class="header-anchor" href="#empfohlene-reihenfolge" aria-label="Permalink to &quot;Empfohlene Reihenfolge&quot;">​</a></h2><ol><li>Nach Hardware <a href="/ultra_guides/de/local/image-gen/a1111">A1111</a> oder <a href="/ultra_guides/de/local/image-gen/comfyui">ComfyUI</a> installieren und Modelle laden</li><li><strong>API + LAN-Listen</strong> (in den Tutorials)</li><li><a href="/ultra_guides/de/local/image-gen/connect-app">MiniTavern verbinden</a> und testen</li><li>Im Chat <code>/imagine</code> oder Anhang → Bild (siehe <a href="/ultra_guides/de/manual/model-link#bildgenerierung-verbindung--antwortbilder--schlüsselwörter">Modellverbindung · Bild</a>)</li><li>Zurück zur <a href="/ultra_guides/de/local/">Lokale-Modelle-Übersicht</a></li></ol><h2 id="wichtige-hinweise" tabindex="-1">Wichtige Hinweise <a class="header-anchor" href="#wichtige-hinweise" aria-label="Permalink to &quot;Wichtige Hinweise&quot;">​</a></h2><ul><li>Auf dem Handy die <strong>LAN-IP</strong> des PCs (z. B. <code>192.168.1.8</code>), <strong>nicht</strong> <code>localhost</code> / <code>127.0.0.1</code>.</li><li>A1111 braucht <strong><code>--api</code></strong>; nur Web-UI reicht nicht.</li><li>ComfyUI braucht <strong><code>--listen</code></strong> (oder Desktop Listen <code>0.0.0.0</code>) fürs Handy.</li><li>Firewall-Ports; unauthentifizierte Bild-APIs nicht öffentlich.</li><li>Aktueller Comfy-Default-Workflow <strong>nutzt keine Referenzbilder</strong>; für Face-Lock eher A1111 oder Cloud mit Referenz.</li></ul>',14)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
